import { SearchParamsContext } from 'next/dist/shared/lib/hooks-client-context.shared-runtime';
import { useState,useEffect } from 'react';
import AgencyCalendarWorkspace from '@/components/AgencyCalendarWorkspace';
import operatingStyles from '@/components/AgencyOperatingWorkspace.module.css';
let tasks:any[]=[];
let failSave=false,failBirthdays=false,failReads=false,inactiveOwner=false;
let failWorkRefresh=false,failWorkWrite=false,denyWork=false,workRevision=1,undoWork:any=null,failedInitialRead=false,releaseWorkRead:(()=>void)|null=null;
const workId='60000000-0000-4000-8000-000000000071';
let connectedWork={work_kind:'task',work_id:workId,title:'Call James about Dylan',display_title:'Call James about Dylan',due_on:'2026-11-28' as string|null,due_at:'2026-11-28T11:00:00Z' as string|null,note:'Discuss the trial dates',status:'open',context:{player_id:'30000000-0000-4000-8000-000000000001'},state:{version:1,status:'open'}};
const workMode=()=>typeof window!=='undefined'&&new URLSearchParams(window.location.search).has('connectedWork');
const rpc=async<T,>(name:string,args:any={}):Promise<T>=>{
 if(typeof window!=='undefined'){const qa=window as any;qa.calendarReads??=[];qa.calendarReads.push({name,args});}
 if(typeof window!=='undefined'&&!(window as any).releaseStalls&&((new URLSearchParams(window.location.search).has('stalled')&&name==='redream_calendar_range')||(new URLSearchParams(window.location.search).has('stalledTasks')&&name==='redream_calendar_tasks_v1')))return new Promise(()=>{});
 if(name==='redream_home_work_v1'){
  if(denyWork||args.p_tenant_id!=='qa-tenant'||args.p_work_id!==workId)throw new Error('home_work_access_denied');
  if(args.p_action==='read'&&new URLSearchParams(window.location.search).has('failFirstWorkRead')&&!failedInitialRead){failedInitialRead=true;throw new Error('Temporary read failure');}
  if(args.p_action==='read'&&new URLSearchParams(window.location.search).has('slowWorkRead'))await new Promise(resolve=>setTimeout(resolve,200));
  if(args.p_action==='read'&&new URLSearchParams(window.location.search).has('stalledWork'))await new Promise<void>(resolve=>{releaseWorkRead=resolve;});
  if(args.p_action!=='read'){
   if(failWorkWrite)throw new Error('Could not confirm the write');
   if(JSON.stringify(args.p_expected_state)!==JSON.stringify(connectedWork.state))throw new Error('home_work_conflict');
   if(args.p_action==='undo')connectedWork={...undoWork};
   else{if(args.p_action==='complete')undoWork={...connectedWork};const input=args.p_input;
    connectedWork={...connectedWork,...(input.title?{title:input.title,display_title:input.title}:{}),...(input.note!==undefined?{note:input.note}:{}),...(Object.hasOwn(input,'due_on')?{due_on:input.due_on,due_at:input.due_on?input.due_on+'T11:00:00Z':null}:{}),...(args.p_action==='complete'?{status:'done'}:{})};}
   connectedWork={...connectedWork,state:{version:++workRevision,status:connectedWork.status}};
  }
  const cancelled=new URLSearchParams(window.location.search).has('cancelledWork');const closed=cancelled||new URLSearchParams(window.location.search).has('completedWork');
  return {work:{...connectedWork,work_kind:args.p_work_kind,status:closed?'done':connectedWork.status,state:{...connectedWork.state,status:closed?'done':connectedWork.status,...(cancelled?{original_status:'cancelled'}:{})}},undo_token:args.p_action==='complete'?'qa-work-undo':null}as T;
 }
 if(name==='redream_assigned_work_page_v1'){
  if(workMode()){if(failWorkRefresh)throw new Error('offline');return {items:args.p_tenant_id==='qa-tenant'&&connectedWork.status==='open'&&!new URLSearchParams(window.location.search).has('completedWork')&&!new URLSearchParams(window.location.search).has('cancelledWork')?[{...connectedWork,responsible_people:[{user_id:'qa-user',display_name:'Jesse'}]}]:[],next_cursor:null,limited:false}as T;}
  return {items:[{work_kind:'task',work_id:'60000000-0000-4000-8000-000000000009',title:'Shared unscheduled follow-up',due_at:null,context:{person_id:'contact'},responsible_people:[{user_id:'qa-user',display_name:'Jesse'}]}],next_cursor:null,limited:false}as T;
 }
 if(name==='redream_calendar_task_assignees_v1')return {items:[{user_id:'qa-user',display_name:'Jesse'},...(!inactiveOwner?[{user_id:'colleague',display_name:'Dapo'}]:[])]}as T;
 if(name==='redream_calendar_task_create_v1'){if(failSave)throw new Error('task_owner_inactive');const input=args.p_input;const task={...input,id:input.id,tenant_id:args.p_tenant_id,creator_user_id:'qa-user',owner_user_id:input.owner_user_id||'qa-user',owner_name:input.owner_user_id==='colleague'?'Dapo':'Jesse',responsible_user_ids:input.responsible_user_ids||[input.owner_user_id||'qa-user'],responsible_people:(input.responsible_user_ids||[input.owner_user_id||'qa-user']).map((user_id:string)=>({user_id,display_name:user_id==='colleague'?'Dapo':'Jesse'})),status:'open',revision:1,archived_at:null,can_edit:true,needs_reassignment:false,due_at:null,notes:input.notes||''};tasks.push(task);return {task}as T;}
 if(name==='redream_calendar_task_update_v1'){if(failSave)throw new Error('task_revision_conflict');const task=tasks.find(t=>t.id===args.p_task_id);if(task.revision!==args.p_expected_revision)throw new Error('task_revision_conflict');if(args.p_action==='edit'){if(inactiveOwner&&task.visibility==='company'&&(args.p_input.responsible_user_ids||task.responsible_user_ids||[task.owner_user_id]).includes('colleague'))throw new Error('task_owner_inactive');Object.assign(task,args.p_input);task.responsible_people=(task.responsible_user_ids||[task.owner_user_id]).map((user_id:string)=>({user_id,display_name:user_id==='colleague'?'Dapo':'Jesse'}));}else if(args.p_action==='complete')task.status='done';else if(args.p_action==='reopen')task.status='open';else if(args.p_action==='archive')task.archived_at=new Date().toISOString();else if(args.p_action==='restore')task.archived_at=null;task.revision++;return {task:{...task}}as T;}
 if(name==='redream_calendar_tasks_v1'){if(failReads)throw new Error('offline');const items=tasks.filter(t=>t.tenant_id===args.p_tenant_id&&(!t.archived_at||args.p_include_archived)&&(t.status==='open'||args.p_include_done)).filter(t=>args.p_mode==='undated'?!t.due_on:args.p_mode==='overdue'?false:t.due_on>=args.p_start&&t.due_on<args.p_end);return {items:items.map(t=>({...t})),next_cursor:null,count:items.length}as T;}
 if(name==='redream_calendar_birthdays'){if(failBirthdays)throw new Error('offline');return {items:[{item_id:'birthday',date_at:args.p_start,title:"Dylan's birthday",birthday_category:'players',player_id:'player'}]}as T;}
 const recordedDates=typeof window!=='undefined'&&new URLSearchParams(window.location.search).has('recordedDates')?[
  {deadline_type:'contract_expiry',entity_id:'qa-contract',deadline_at:'2026-11-28T00:00:00+00:00',date_only:true,title:'Recorded contract expiry',context:{player_id:'player'}},
  {deadline_type:'representation_record_end',entity_id:'qa-agreement',deadline_at:'2026-11-29T00:00:00+00:00',date_only:true,title:'Recorded agency agreement',context:{player_id:'player'}},
  {deadline_type:'document_expiry',entity_id:'qa-document',deadline_at:'2026-11-30T00:00:00+00:00',date_only:true,title:'Recorded document expiry',context:{player_id:'player'}}
 ].filter(item=>item.deadline_at.slice(0,10)>=args.p_start&&item.deadline_at.slice(0,10)<args.p_end):[];
 return {meetings:{items:[{meeting_id:'meeting',title:'Club meeting',starts_at:args.p_start+'T20:00:00',person_name:'Club contact'}]},follow_ups:{items:[]},operations:{deadlines:{items:recordedDates}}}as T;
};
export default function Page(){const [tenant,setTenant]=useState('qa-tenant');const[search,setSearch]=useState(new URLSearchParams());useEffect(()=>setSearch(new URLSearchParams(window.location.search)),[]);return <SearchParamsContext.Provider value={search}><main className={operatingStyles.root} style={{maxWidth:1150,margin:'0 auto',padding:16,fontFamily:'Arial,sans-serif',background:'#f5f7f9','--agency-primary':'#12364c'}as any}><h1 id="workspace-view-heading" tabIndex={-1}>Calendar</h1><div className={operatingStyles.viewStage}><AgencyCalendarWorkspace key={tenant} tenantId={tenant} userId="qa-user" preferenceKey={`${tenant}:qa-user`} data={{}} basePath="/qa-calendar" rpc={rpc} onRecordMeetingOutcome={()=>{}}/></div><nav aria-label="Fixture navigation" style={{position:"fixed",bottom:20,left:20,right:20,height:70,zIndex:1000,background:"white"}}>Home Players Calendar</nav><button aria-label="Fixture microphone" style={{position:"fixed",bottom:110,right:20,zIndex:10000}}>Mic</button><button onClick={()=>{connectedWork={...connectedWork,status:"done",state:{version:++workRevision,status:"done"}};}}>Complete follow-up in another session</button><button onClick={()=>releaseWorkRead?.()}>Release follow-up read</button><button onClick={()=>{failWorkRefresh=!failWorkRefresh;}}>Toggle follow-up refresh failure</button><button onClick={()=>{failWorkWrite=!failWorkWrite;}}>Toggle follow-up write failure</button><button onClick={()=>{denyWork=!denyWork;}}>Toggle follow-up access</button><button onClick={()=>{connectedWork={...connectedWork,title:"Changed in another session",display_title:"Changed in another session",state:{...connectedWork.state,version:++workRevision}};}}>Concurrent follow-up edit</button><button onClick={()=>{failSave=!failSave;}}>Toggle save failure</button><button onClick={()=>{failBirthdays=!failBirthdays;window.dispatchEvent(new Event('redream:birthdays-updated'));}}>Toggle birthday failure</button><button onClick={()=>{inactiveOwner=!inactiveOwner;}}>Toggle inactive owner</button><button onClick={()=>{failReads=!failReads;}}>Toggle task read failure</button><button onClick={()=>{const task=tasks.find(t=>t.title==='Revised shortlist');task.title='Other session shortlist';task.revision++;}}>Concurrent edit</button><button onClick={()=>setTenant(tenant==='qa-tenant'?'other-tenant':'qa-tenant')}>Switch tenant</button></main></SearchParamsContext.Provider>;}
